changeSet.rollback:
create or alter procedure [fusion].[GenerateMarkitMapLineage] as begin SET NOCOUNT, ANSI_PADDING ON; SET ANSI_WARNINGS ON;
update M set M.[SourceIntersectID] = OI.ID from [fusion].[MarkitLineageMapping] M inner join Asset S on S.ID = M.SourceAssetID inner join Asset O on O.ID = M.ObjectAssetID inner join [IntersectDetail] OI on OI.[Subject] = S.[Object] and OI.SubjectID = S.ObjectID and OI.[Object] = O.[Object] and OI.[ObjectID] = O.[ObjectID];
update M set M.[SourceIntersectID] = OI.ID from [fusion].[MarkitLineageMapping] M inner join Asset S on S.ID = M.SourceAssetID inner join Asset O on O.ID = M.ObjectAssetID inner join [IntersectDetail] OI on OI.[Object] = S.[Object] and OI.ObjectID = S.[ObjectID] and OI.[Subject] = O.[Object] and OI.[SubjectID] = O.[ObjectID] and M.SourceIntersectID is null
insert into [intersect] (IntersectTypeID, [Subject], SubjectID, [Object], ObjectID, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, [Owner]) select distinct (select top 1 IT.ID from [IntersectType] IT inner join [Predicate] P on IT.[predicateid] = P.ID where (P.[Type] not in (3,4) and (IT.[Object] = O.[Type] and IT.[Subject] = S.[Type] and IT.ObjectID = O.TypeID and IT.SubjectID = S.TypeID))) ,S.[Object] ,S.[ObjectID] ,O.[Object] ,O.[ObjectID] ,0,getutcdate(),0,getutcdate(),'MARKIT LINEAGE' from [fusion].[MarkitLineageMapping] M inner join AssetDetail O on O.ID = M.ObjectAssetID inner join AssetDetail S on S.ID = M.SourceAssetID where M.SourceIntersectID is null;
update M set M.[SourceIntersectID] = OI.ID from [fusion].[MarkitLineageMapping] M inner join Asset S on S.ID = M.SourceAssetID inner join Asset O on O.ID = M.ObjectAssetID inner join [IntersectDetail] OI on OI.[Subject] = S.[Object] and OI.SubjectID = S.[ObjectID] and OI.[Object] = O.[Object] and OI.[ObjectID] = O.[ObjectID] and M.SourceIntersectID is null;
update M set M.[TargetIntersectID] = OI.ID from [fusion].[MarkitLineageMapping] M inner join Asset T on T.ID = M.TargetAssetID inner join Asset O on O.ID = M.ObjectAssetID inner join [IntersectDetail] OI on OI.[Subject] = T.[Object] and OI.SubjectID = T.[ObjectID] and OI.[Object] = O.[Object] and OI.[ObjectID] = O.[ObjectID]
update M set M.[TargetIntersectID] = OI.ID from [fusion].[MarkitLineageMapping] M inner join Asset T on T.ID = M.TargetAssetID inner join Asset O on O.ID = M.ObjectAssetID inner join [IntersectDetail] OI on OI.[Object] = T.[Object] and OI.ObjectID = T.[ObjectID] and OI.[Subject] = O.[Object] and OI.[SubjectID] = O.[ObjectID] and M.TargetIntersectID is null;
insert into [intersect] (IntersectTypeID, [Subject], SubjectID, [Object], ObjectID, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, [Owner]) select distinct (select top 1 IT.ID from [intersecttype] IT inner join [Predicate] P on IT.[predicateid] = P.ID where (P.[Type] not in (3,4) and (IT.[Object] = O.[Type] and IT.[Subject] = T.[Type] and IT.ObjectID = O.TypeID and IT.SubjectID = T.TypeID))) ,T.[Object] ,T.[ObjectID] ,O.[Object] ,O.[ObjectID] ,0,getutcdate(),0,getutcdate(),'MARKIT LINEAGE' from [fusion].[MarkitLineageMapping] M inner join AssetDetail O on O.ID = M.ObjectAssetID inner join AssetDetail T on T.ID = M.TargetAssetID where M.TargetIntersectID is null;
update M set M.[TargetIntersectID] = OI.ID from [fusion].[MarkitLineageMapping] M inner join Asset T on T.ID = M.TargetAssetID inner join Asset O on O.ID = M.ObjectAssetID inner join [IntersectDetail] OI on OI.[Subject] = T.[Object] and OI.SubjectID = T.[ObjectID] and OI.[Object] = O.[Object] and OI.[ObjectID] = O.[ObjectID] and M.TargetIntersectID is null;
print 'Removing any prior generated Markit Lineage map records';
delete from mapruleitemmapitem where [owner] = 'MARKIT LINEAGE';
print 'Inserting new map records';
Declare @MapItemIDList Table(MapItemID int, sourceintersectid int, targetintersectid int); Declare @MapRuleItemIDList Table(MapRuleItemID int, MapID Int);
update T set T.MapItemID = mi.ID from [fusion].[MarkitLineageMapping] T inner join mapitem mi on(T.SourceIntersectID = mi.SourceIntersectID and T.TargetIntersectID = mi.TargetIntersectID and mi.[Owner] = 'MARKIT LINEAGE');
MERGE INTO mapitem mi USING ( select distinct sourceintersectid, targetintersectid FROM [fusion].[MarkitLineageMapping] where (sourceintersectid is not null and targetintersectid is not null) and sourceintersectid != targetintersectid and coalesce(mapitemid, 0) = 0 ) S ON (1 = 0) WHEN NOT MATCHED THEN INSERT (SourceIntersectID, TargetIntersectID, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, [Owner]) VALUES (S.sourceintersectid, S.targetintersectid, 0, getutcdate(), 0, getutcdate(), 'MARKIT LINEAGE') OUTPUT INSERTED.ID, S.sourceintersectid, S.targetintersectid into @MapItemIDList;
update T set T.mapitemid = MI.MapItemID from [fusion].[MarkitLineageMapping] T inner join @MapItemIDList MI on (MI.SourceIntersectID = T.SourceIntersectID and MI.TargetIntersectID = T.TargetIntersectID)
delete from mapitem where [owner] = 'MARKIT LINEAGE' and id not in (select mapitemid from [fusion].[MarkitLineageMapping]);
update T set T.mapruleitemid = S.id from [fusion].[MarkitLineageData] T inner join [dbo].[mapruleitem] S on (S.[owner] = 'MARKIT LINEAGE' and S.SourceFusionAttributeID = T.SourceFusionAttributeID and S.TargetFusionAttributeID = T.TargetFusionAttributeID);
MERGE INTO mapruleitem mri USING ( select SourceFusionAttributeID, TargetFusionAttributeID, ID from [fusion].[MarkitLineageData] where coalesce(mapruleitemid, 0) = 0 ) S ON (1 = 0) WHEN NOT MATCHED THEN INSERT (SourceFusionAttributeID, TargetFusionAttributeID, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, [Owner]) VALUES (S.SourceFusionAttributeID, S.TargetFusionAttributeID, 0, getutcdate(), 0, getutcdate(), 'MARKIT LINEAGE') OUTPUT INSERTED.ID, S.ID into @MapRuleItemIDList;
update T set T.MapRuleItemID = MI.MapRuleItemID from [fusion].[MarkitLineageData] T inner join @MapRuleItemIDList MI on (MI.MapID = T.ID);
delete from mapruleitem where [owner] = 'MARKIT LINEAGE' and id not in (select MapRuleItemID from [fusion].[MarkitLineageData]);
insert into mapruleitemmapitem (MapRuleItemID, MapItemID, [Owner]) SELECT distinct M.MapRuleItemID, O.MapItemID , 'MARKIT LINEAGE' FROM [fusion].[MarkitLineageData] M inner join [fusion].[MarkitLineageMapping] O on O.MapID = M.ID where coalesce(M.MapRuleItemID, 0) != 0 and coalesce(O.MapItemID, 0) != 0;
declare @mapruleitemmapitemCount int; select @mapruleitemmapitemCount = count(1) from mapruleitemmapitem where [owner] = 'MARKIT LINEAGE' print 'Inserted [' + cast(@mapruleitemmapitemCount as varchar) + '] mapruleitemmapitem records';
declare @mapruleitemCount int; select @mapruleitemCount = count(1) from mapruleitem where [owner] = 'MARKIT LINEAGE' print 'Inserted [' + cast(@mapruleitemCount as varchar) + '] mapruleitem records';
declare @mapitemCount int; select @mapitemCount = count(1) from mapitem where [owner] = 'MARKIT LINEAGE' print 'Inserted [' + cast(@mapitemCount as varchar) + '] mapitem records';
end
